import React, { useMemo, useState } from 'react';
import { useTranslation } from '../../hooks/useTranslation';
import { getApiBaseUrl } from '../../lib/config';

interface ShareLinkPreviewProps {
  shortUrl: string;
  formTitle: string;
}

/**
 * The image people see when this form's link is shared (WhatsApp, Slack, LinkedIn…).
 * Generated by the backend (/og/forms/<shortUrl>.png) from the form's title and
 * background; the form viewer's edge worker puts it in the page's og:image tag.
 * Hidden when the image can't load (e.g. the form is still a draft).
 */
export const ShareLinkPreview: React.FC<ShareLinkPreviewProps> = ({ shortUrl, formTitle }) => {
  const { t } = useTranslation('collectResponses');
  const [failed, setFailed] = useState(false);
  // A fresh URL per open, so a just-edited title or background shows up here
  // instead of the CDN's cached copy (social apps get the versioned URL).
  const src = useMemo(
    () => `${getApiBaseUrl().replace(/\/+$/, '')}/og/forms/${encodeURIComponent(shortUrl)}.png?t=${Date.now()}`,
    [shortUrl]
  );

  if (failed) return null;

  return (
    <div className="space-y-1.5 pt-2" data-testid="share-link-preview">
      <p className="text-sm font-medium text-primary">{t('link.preview.title')}</p>
      <div
        className="overflow-hidden rounded-xl bg-muted"
        style={{ border: '1px solid var(--tf-border-medium)', aspectRatio: '1200 / 630' }}
      >
        <img
          src={src}
          alt={t('link.preview.alt', { values: { title: formTitle } })}
          className="h-full w-full object-cover"
          loading="lazy"
          onError={() => setFailed(true)}
        />
      </div>
      <p className="text-xs text-muted-foreground">{t('link.preview.help')}</p>
    </div>
  );
};
